const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const code=()=> 'PR-'+Array.from(crypto.getRandomValues(new Uint8Array(10)),b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();
const initial=()=>({code:code(),chats:[{id:'welcome',name:'PRYMA welcome',initials:'P',color:'#dce6c9',days:0,messages:[{id:crypto.randomUUID(),text:'A quieter space for your conversations. Welcome to PRYMA.',mine:false,time:Date.now()},{id:crypto.randomUUID(),text:'Your code opens the conversation. You decide what stays.',mine:false,time:Date.now()},{id:crypto.randomUUID(),text:'Try writing a message below. This preview keeps it here; it won’t be sent to another person.',mine:false,time:Date.now()}]}],requests:[{id:'r1',name:'Alex · sample request',code:'PR-DEMO-ALEX',initials:'A'}]});
let state=initial(),selected='welcome',view='chats',key=null,salt=null,locked=!!localStorage.getItem('pryma-vault-v1'),saveChain=Promise.resolve();
const toast=t=>{ $('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3500)};
function modal(html,submit){$('#modalBody').innerHTML=html;$('#modalForm').onsubmit=async e=>{e.preventDefault();if(submit)await submit()};$('#dialog').showModal()}
$('#closeDialog').onclick=()=>$('#dialog').close();
const b64=a=>btoa(String.fromCharCode(...new Uint8Array(a))),un64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function derive(password,s){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:600000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function persist(){if(!key)return;const snapshot=JSON.stringify(state),k=key,s=salt;saveChain=saveChain.catch(()=>{}).then(async()=>{const iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(snapshot));localStorage.setItem('pryma-vault-v1',JSON.stringify({v:1,salt:b64(s),iv:b64(iv),data:b64(encrypted)}))});try{await saveChain}catch(e){toast('Could not save the vault. Keep this tab open.');throw e}}
function vault(unlock=false){modal(`<span class="eyebrow">ON THIS BROWSER</span><h2>${unlock?'Unlock your space':'Keep your conversations'}</h2><p>${unlock?'Enter your vault password. There is no password recovery.':'Create a password of at least 12 characters. This encrypts your local history in this browser. It does not enable remote messaging or end-to-end encryption. Losing the password or browser data loses this vault.'}</p><label for="password">Vault password</label><input id="password" type="password" minlength="12" required autocomplete="${unlock?'current-password':'new-password'}"><p class="error" id="vaultError"></p><button class="primary">${unlock?'Unlock vault':'Create encrypted vault'}</button>`,async()=>{const button=$('#modalBody .primary');button.disabled=true;try{if(unlock){const packet=JSON.parse(localStorage.getItem('pryma-vault-v1'));const s=un64(packet.salt),k=await derive($('#password').value,s);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(packet.iv)},k,un64(packet.data));const parsed=JSON.parse(new TextDecoder().decode(plain));state=parsed;key=k;salt=s;locked=false;selected=state.chats[0]?.id;expire();}else{salt=crypto.getRandomValues(new Uint8Array(16));key=await derive($('#password').value,salt);await persist()}$('#dialog').close();render();toast(unlock?'Vault unlocked':'Encrypted vault saved on this browser')}catch(e){$('#vaultError').textContent=unlock?'Unable to unlock. Check your password and try again.':'Unable to save the vault. Browser storage may be unavailable.'}finally{button.disabled=false}})}
function expire(){let change=false;for(const c of state.chats){const n=c.messages.length;c.messages=c.messages.filter(m=>!m.expires||m.expires>Date.now());if(n!==c.messages.length)change=true}if(change)persist();return change}
function render(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageTitle').textContent=({chats:'Conversations',requests:'Connection requests',identity:'Your private identity',settings:'Your preferences'})[view];$('#chatCount').textContent=locked?'':state.chats.length;const q=$('#search').value.toLowerCase();$('#chatList').innerHTML=locked?'':state.chats.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<button class="chatItem ${selected===c.id&&view==='chats'?'current':''}" data-chat="${c.id}" aria-label="${esc(c.name)}"><span class="avatar" style="background:${c.color}">${esc(c.initials)}</span><span class="chatInfo"><strong>${esc(c.name)}</strong><p>${esc(c.messages.at(-1)?.text||'Start something good.')}</p></span><span class="chatTime">local</span></button>`).join('');document.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{selected=b.dataset.chat;view='chats';render()});
if(locked){$('#workspace').innerHTML='<div class="contentpage"><h2>Your space is locked.</h2><p class="lede">Unlock your encrypted local vault to continue.</p><button class="primary" id="unlock">Unlock vault</button></div>';$('#unlock').onclick=()=>vault(true);return}
if(view==='chats')renderChat();if(view==='identity')renderIdentity();if(view==='requests')renderRequests();if(view==='settings')renderSettings();}
function renderChat(){const c=state.chats.find(x=>x.id===selected);if(!c){$('#workspace').innerHTML='<div class="contentpage"><h2>A little space for connection.</h2><p class="lede">Create a local conversation with a PRYMA code to explore the experience.</p><button class="primary" id="first">New conversation</button></div>';$('#first').onclick=newChat;return}$('#workspace').innerHTML=`<div class="conversation"><div class="conversationHeader"><div class="avatar" style="background:${c.color}">${esc(c.initials)}</div><div><h3>${esc(c.name)}</h3><small>Browser-only conversation · not connected</small></div><span class="previewTag">◈ &nbsp; Your conversation, your rules</span><button id="clear" aria-label="Delete local conversation" title="Delete local conversation">⋯</button></div><div class="messages" id="messages"><div class="day">A FRESH START</div><div class="welcome"><div class="seal">♧</div><h3>Good conversations need a little space.</h3><p>No number to share. No feed to follow.<br>Just a conversation, on your terms.</p></div>${c.messages.map(m=>`<div class="message ${m.mine?'mine':''}"><div class="bubble">${esc(m.text)}</div><div class="meta">${new Date(m.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · ${m.mine?'Local only':'Sample message'}${m.expires?' · Expires '+new Date(m.expires).toLocaleDateString():''}<button data-export="${m.id}">Export ↗</button></div></div>`).join('')}</div><div class="controls"><label for="retention">◷ &nbsp; Disappear</label><select id="retention"><option value="0">Off · keep here</option><option value="1">After 1 day</option><option value="7">After 7 days</option><option value="30">After 30 days</option></select><span>${key?'Local vault enabled':'Session only'} &nbsp; · &nbsp; Sync off</span></div><form class="composer" id="composer"><textarea id="message" maxlength="10000" placeholder="A message, just between us…" aria-label="Message"></textarea><button class="send" aria-label="Save message locally" title="Save message locally">↑</button></form></div>`;$('#retention').value=c.days;$('#retention').onchange=async e=>{c.days=Number(e.target.value);await persist();toast('Applies to new messages, from creation time. Copies may remain.')};$('#composer').onsubmit=async e=>{e.preventDefault();const text=$('#message').value.trim();if(!text)return;c.messages.push({id:crypto.randomUUID(),mine:true,text,time:Date.now(),expires:c.days?Date.now()+c.days*86400000:null});await persist();render()};$('#message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#composer').requestSubmit()}};$('#clear').onclick=()=>modal('<h2>Delete this conversation?</h2><p>This removes this browser’s copy. It cannot delete exports or copies held elsewhere.</p><button class="primary">Delete local conversation</button>',async()=>{state.chats=state.chats.filter(x=>x.id!==c.id);selected=state.chats[0]?.id;await persist();$('#dialog').close();render()});document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportMessage(c,c.messages.find(m=>m.id===b.dataset.export)));$('#messages').scrollTop=$('#messages').scrollHeight;}
function newChat(){if(locked)return vault(true);modal('<span class="eyebrow">A CONNECTION STARTS WITH A CODE</span><h2>Say hello.</h2><p>Create a local conversation preview. Codes are not looked up and no request is sent in this version.</p><label for="contactName">Name on this device</label><input id="contactName" required maxlength="50" placeholder="e.g. Alex"><label for="contactCode">Their PRYMA code</label><input id="contactCode" required pattern="PR-[A-Za-z0-9-]{6,}" placeholder="PR-…"><button class="primary">Create local conversation</button>',async()=>{const id=crypto.randomUUID(),name=$('#contactName').value.trim();if(!name)return;state.chats.push({id,name,initials:name.slice(0,2).toUpperCase(),code:$('#contactCode').value.trim(),color:'#e6e2d6',days:0,messages:[]});selected=id;view='chats';await persist();$('#dialog').close();render()})}
function renderIdentity(){$('#workspace').innerHTML=`<div class="contentpage"><span class="eyebrow">REACHABLE. ON YOUR TERMS.</span><h2>You are more than a phone number.</h2><p class="lede">A code to open a conversation. A little more control over who gets to reach you.</p><div class="card"><span class="tag">LOCAL PREVIEW IDENTITY</span><div class="code">${esc(state.code)}</div><button class="primary" id="copyCode">Copy my code</button><button class="secondary" id="rotate">Generate a new code</button><p>This preview code lives here. It is not registered with a messaging directory and cannot receive messages.</p></div><div class="card"><h3>One device. One clear boundary.</h3><p>Only this browser is active. Device linking, verification QR codes and remote code discovery are planned for the secure alpha.</p></div></div>`;$('#copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(state.code);toast('Code copied')}catch{toast('Select and copy the displayed code')}};$('#rotate').onclick=async()=>{state.code=code();await persist();renderIdentity();toast('New local preview code created')};}
function renderRequests(){$('#workspace').innerHTML=`<div class="contentpage"><span class="eyebrow">YOU CHOOSE WHO GETS IN</span><h2>A hello is an invitation.</h2><p class="lede">Unknown connections begin here. Explore the approval flow with a sample request.</p>${state.requests.map(r=>`<div class="card row"><div class="avatar">${r.initials}</div><div class="grow"><h3>${esc(r.name)}</h3><p>${esc(r.code)} · simulated</p></div><button class="secondary" data-block="${r.id}">Dismiss</button><button class="primary" data-accept="${r.id}">Accept locally</button></div>`).join('')||'<div class="card"><h3>All quiet here.</h3><p>No pending sample requests.</p></div>'}</div>`;document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{state.requests=state.requests.filter(r=>r.id!==b.dataset.block);await persist();render()});document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{const r=state.requests.find(r=>r.id===b.dataset.accept),id=crypto.randomUUID();state.chats.push({id,name:r.name,initials:r.initials,color:'#e4ded2',code:r.code,days:0,messages:[]});state.requests=state.requests.filter(x=>x!==r);selected=id;view='chats';await persist();render()})}
function renderSettings(){$('#workspace').innerHTML=`<div class="contentpage"><span class="eyebrow">PRIVATE BY DEFAULT. YOURS BY DESIGN.</span><h2>Make yourself at home.</h2><p class="lede">Know what stays, where it lives, and what this first version can do.</p><div class="card"><h3>Local history</h3><p>${key?'Your history is encrypted at rest in this browser. Lock your vault when you step away.':'Your messages exist only in this tab’s memory and disappear on reload. Create a password-protected vault to keep them on this browser.'}</p><button class="primary" id="vaultButton">${key?'Lock vault':'Enable encrypted local vault'}</button><p class="footnote">AES-GCM local storage encryption. This is not end-to-end messaging. Anyone with access to an unlocked tab can read its content.</p></div><div class="card"><div class="checkrow"><span>Phone number / address book</span><span class="tag">Not collected</span></div><div class="checkrow"><span>AI access to conversations</span><span class="tag">None</span></div><div class="checkrow"><span>Device sync / backups</span><span>Not connected</span></div><div class="checkrow"><span>CERVEL integration</span><span>Manual JSON export only</span></div></div><button class="secondary danger" id="reset">Erase local preview data</button><p class="footnote">No message analytics are sent. The hosting provider may receive ordinary request metadata.</p></div>`;$('#vaultButton').onclick=async()=>{if(!key)return vault();await persist();key=null;salt=null;state=initial();locked=true;render()};$('#reset').onclick=()=>modal('<h2>Erase local preview data?</h2><p>This removes this browser’s vault and all current preview conversations. This cannot be undone. Exports elsewhere will remain.</p><button class="primary">Erase local data</button>',async()=>{await saveChain.catch(()=>{});localStorage.removeItem('pryma-vault-v1');key=null;salt=null;locked=false;state=initial();selected='welcome';$('#dialog').close();render();toast('Local preview reset')})}
function exportMessage(c,m){modal(`<h2>Export this message?</h2><p>This downloads a separate JSON copy for manual review. It is not saved to CERVEL automatically. The copy has its own retention rules and may disclose the other participant’s message.</p><div class="card"><p>${esc(m.text)}</p></div><button class="primary">Download selected message</button>`,()=>{const blob=new Blob([JSON.stringify({format:'pryma-message-export-v1',source:'PRYMA local preview',conversation:c.name,createdAt:new Date(m.time).toISOString(),exportedAt:new Date().toISOString(),author:m.mine?'self':'sample',content:m.text},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pryma-message.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#dialog').close();toast('Selected message exported; no CERVEL connection used')})}
$('#search').oninput=render;$('#newChat').onclick=newChat;$('#myCode').onclick=()=>{view='identity';render()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#about').onclick=()=>modal('<h2>A first space for PRYMA.</h2><p><b>Working:</b> local conversations, code generation, sample request approval, local expiration, selected-message export and password-encrypted local history.</p><p><b>Still to build:</b> real contacts, network delivery, audited end-to-end encryption, device verification, mobile clients and CERVEL integration.</p><p>This preview is for exploring the experience. Do not use it for sensitive conversations.</p>');setInterval(()=>{if(!locked&&expire()&&view==='chats')renderChat()},10000);render();
